from addict import Dict

def test_init_with_list_of_tuples():
    b = [(0, 1), (1, 2), (2, 3)]
    a = Dict(b)
    assert a == {0: 1, 1: 2, 2: 3}

import pytest
import gpustat

def test_gpustat_nvidia_hardware():
    try:
        gpustat.new_query()
    except Exception as e:
        if 'NVSMI' in str(e) or 'NVML' in str(e) or 'driver' in str(e).lower():
            pytest.fail(f'Missing NVIDIA GPU hardware/NVML driver: {e}')
        raise
